import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.DbSlGjul.js";const p=JSON.parse('{"title":"Evaluation protocol","description":"","frontmatter":{},"headers":[],"relativePath":"benchmark/protocol.md","filePath":"benchmark/protocol.md","lastUpdated":1788882780000}'),o={name:"benchmark/protocol.md"};function l(n,e,s,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="evaluation-protocol" tabindex="-1">Evaluation protocol <a class="header-anchor" href="#evaluation-protocol" aria-label="Permalink to &quot;Evaluation protocol&quot;">​</a></h1><p>This protocol characterizes robot-side performance across HiveBoard attachments. It is suitable for teleoperated arms, wearable interfaces, exoskeletons, and autonomous policies, provided that the control mode is held constant across the recorded trials being compared.</p><p>The source protocol is available in <a href="https://github.com/EESC-LabRoM/HiveBoard/blob/main/Documentation/PROTOCOL.md" target="_blank" rel="noreferrer"><code>Documentation/PROTOCOL.md</code></a>. Submissions through this documentation require all 13 conditions, with five recorded trials per condition (65 trials).</p><h2 id="required-material" tabindex="-1">Required material <a class="header-anchor" href="#required-material" aria-label="Permalink to &quot;Required material&quot;">​</a></h2><ul><li>One printed HiveBoard base.</li><li>The complete attachment set, including the four-piece friction-ring accessory for the ball-valve ring condition.</li><li>One manipulation platform: an end-effector plus the system that positions and commands it.</li><li>The <a href="/hivedocs/benchmark/evaluation-runner">Evaluation Runner</a> or supplied trial logging template.</li><li>An external camera with a view of the board and end-effector.</li></ul><h2 id="prepare-the-setup" tabindex="-1">Prepare the setup <a class="header-anchor" href="#prepare-the-setup" aria-label="Permalink to &quot;Prepare the setup&quot;">​</a></h2><ol><li>Fix the board to a rigid surface within the platform&#39;s working volume.</li><li>Record whether it is mounted horizontally or vertically.</li><li>Fully seat every attachment before starting.</li><li>Position the platform so that the board is not moved during a trial.</li><li>Save a photograph of the complete setup as <code>setup.jpg</code>.</li><li>Create <code>platform.md</code> with the end-effector, control interface or policy, mounting orientation, control mode, and relevant calibration notes.</li><li>Record the printer, material, print settings, and post-processing. The runner includes these fields in <code>platform.md</code>.</li></ol><h2 id="familiarization" tabindex="-1">Familiarization <a class="header-anchor" href="#familiarization" aria-label="Permalink to &quot;Familiarization&quot;">​</a></h2><p>Run unrecorded practice trials for each attachment until completion times stabilize. Begin recording after three consecutive practice trials finish within 20% of each other or within the timeout, whichever comes first.</p><p>Practice trials are not included in the submitted result.</p><h2 id="recorded-trials" tabindex="-1">Recorded trials <a class="header-anchor" href="#recorded-trials" aria-label="Permalink to &quot;Recorded trials&quot;">​</a></h2><p>For each platform and attachment pair:</p><ol><li>Run <strong>five recorded trials</strong>.</li><li>Start the end-effector from the same neutral pose.</li><li>Start the external camera before the countdown. When using the runner, command the first task motion when the countdown reaches zero; this is when timing starts. For manual logging, start timing with the first commanded task motion.</li><li>Stop timing when the success criterion is met, a safety event occurs, or the timeout expires.</li><li>Reset the mechanism and neutral pose before the next trial.</li></ol><p>Run the ball valve as two separate blocks: five trials without a friction ring and five with the ring fitted.</p><p>Do not tune parameters or change the control mode between recorded trials in the same condition. A restarted approach inside a trial is counted as another attempt or regrasp; it is not a new trial.</p><h2 id="outcomes" tabindex="-1">Outcomes <a class="header-anchor" href="#outcomes" aria-label="Permalink to &quot;Outcomes&quot;">​</a></h2><p>Use exactly one of these values:</p><table tabindex="0"><thead><tr><th>Outcome</th><th>Meaning</th></tr></thead><tbody><tr><td><code>success</code></td><td>The full success criterion was completed within the timeout</td></tr><tr><td><code>fail</code></td><td>The trial ended unsuccessfully before the timeout</td></tr><tr><td><code>timeout</code></td><td>The success criterion was not completed before the limit</td></tr><tr><td><code>safety_stop</code></td><td>The trial ended because of a safety event</td></tr></tbody></table><p>Only successful trials receive a <code>completion_time_s</code> value.</p><h2 id="failure-causes" tabindex="-1">Failure causes <a class="header-anchor" href="#failure-causes" aria-label="Permalink to &quot;Failure causes&quot;">​</a></h2><p>Every unsuccessful trial must contain one dominant failure cause.</p><table tabindex="0"><thead><tr><th>Cause</th><th>Use when</th></tr></thead><tbody><tr><td><code>grasp_geometry</code></td><td>The end-effector cannot engage the part in a stable grasp</td></tr><tr><td><code>kinematic_limit</code></td><td>The platform cannot produce the motion required by the task</td></tr><tr><td><code>perception</code></td><td>Alignment or state could not be judged reliably</td></tr><tr><td><code>slip</code></td><td>A grasp was acquired and then lost</td></tr><tr><td><code>force_limit</code></td><td>Available grasp or actuation force was insufficient</td></tr><tr><td><code>control_precision</code></td><td>Control resolution was too coarse for the task</td></tr><tr><td><code>other</code></td><td>None of the listed causes fits; explain in <code>notes</code></td></tr></tbody></table><p>Choose one primary cause even when several factors contributed.</p><h2 id="broken-or-displaced-parts" tabindex="-1">Broken or displaced parts <a class="header-anchor" href="#broken-or-displaced-parts" aria-label="Permalink to &quot;Broken or displaced parts&quot;">​</a></h2><p>If a part breaks or leaves its cell:</p><ol><li>stop the trial if continuation is unsafe;</li><li>record the trial as it occurred;</li><li>describe the event in <code>notes</code>;</li><li>reseat or replace the part; and</li><li>continue with the next scheduled trial.</li></ol><p>Do not silently replace the affected row with a rerun.</p><h2 id="reproducibility-checklist" tabindex="-1">Reproducibility checklist <a class="header-anchor" href="#reproducibility-checklist" aria-label="Permalink to &quot;Reproducibility checklist&quot;">​</a></h2><ul><li>[ ] The HiveBoard release or commit is recorded.</li><li>[ ] Printing parameters and post-processing are recorded.</li><li>[ ] All attachments are fully seated.</li><li>[ ] Familiarization is complete for every attachment.</li><li>[ ] Five recorded trials exist for all 13 conditions (65 trials total).</li><li>[ ] Timeouts and task criteria match the module reference.</li><li>[ ] Every unsuccessful trial has one failure cause.</li><li>[ ] Attempts, regrasps, and strategy are present on every row.</li><li>[ ] Composed tasks include <code>stage_reached</code>.</li><li>[ ] Broken or reseated parts are described.</li><li>[ ] <code>setup.jpg</code> and <code>platform.md</code> accompany the log.</li><li>[ ] One external-camera recording accompanies each trial, using the filenames in <code>recording-instructions.md</code>.</li><li>[ ] No operator names or personal identifiers appear in the files.</li></ul>',29)])])}const m=t(o,[["render",l]]);export{p as __pageData,m as default};
